<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
class ExpenseController extends Controller
{
    private function stations(Request $request){return $request->user()->role==='Super Admin'?DB::table('stations')->where('active',true)->pluck('id'):$request->user()->stations()->where('stations.active',true)->pluck('stations.id');}
    public function edit(Request $request,int $expense){abort_unless($request->user()->hasPermission('expenses.manage'),403);$ids=$this->stations($request);$record=DB::table('expenses')->join('expense_categories','expense_categories.id','=','expenses.category_id')->whereNull('expenses.deleted_at')->whereIn('expenses.station_id',$ids)->where('expenses.id',$expense)->select('expenses.*','expense_categories.name as category')->first();abort_unless($record,404);$stations=DB::table('stations')->whereIn('id',$ids)->orderBy('name')->get();return view('expenses.edit',compact('record','stations'));}
    public function update(Request $request,int $expense){abort_unless($request->user()->hasPermission('expenses.manage'),403);$ids=$this->stations($request);$record=DB::table('expenses')->where('id',$expense)->whereNull('deleted_at')->whereIn('station_id',$ids)->first();abort_unless($record,404);$data=$request->validate(['category'=>'required|string|max:100','amount'=>'required|numeric|gt:0','expense_date'=>'required|date','payment_mode'=>'required|in:Cash,UPI,Bank,Card','remarks'=>'nullable|string|max:2000']);DB::transaction(function()use($request,$record,$data){$category=DB::table('expense_categories')->where('station_id',$record->station_id)->where('name',$data['category'])->first();$categoryId=$category?->id??DB::table('expense_categories')->insertGetId(['station_id'=>$record->station_id,'name'=>$data['category'],'created_at'=>now(),'updated_at'=>now()]);DB::table('expenses')->where('id',$record->id)->update(['category_id'=>$categoryId,'amount'=>$data['amount'],'expense_date'=>$data['expense_date'],'payment_mode'=>$data['payment_mode'],'remarks'=>$data['remarks']??null,'updated_at'=>now()]);DB::table('audit_logs')->insert(['user_id'=>$request->user()->id,'station_id'=>$record->station_id,'action'=>'expense_updated','entity_type'=>'expense','entity_id'=>$record->id,'details'=>json_encode($data),'created_at'=>now(),'updated_at'=>now()]);});return redirect()->route('expenses.index')->with('success','Expense updated and recorded in the audit log.');}
    public function index(Request $request){abort_unless($request->user()->hasPermission('expenses.view'),403);$ids=$this->stations($request);$expenses=DB::table('expenses')->join('stations','stations.id','=','expenses.station_id')->join('expense_categories','expense_categories.id','=','expenses.category_id')->join('users','users.id','=','expenses.created_by')->whereNull('expenses.deleted_at')->whereIn('expenses.station_id',$ids)->orderByDesc('expense_date')->select('expenses.*','stations.name as station_name','expense_categories.name as category_name','users.name as creator')->paginate(50);return view('expenses.index',compact('expenses'));}
    public function store(Request $request){abort_unless($request->user()->hasPermission('expenses.manage'),403);$data=$request->validate(['station_id'=>'required|integer','category'=>'required|string|max:100','amount'=>'required|numeric|gt:0','expense_date'=>'required|date','payment_mode'=>'required|in:Cash,UPI,Bank,Card','remarks'=>'nullable|string|max:2000']);abort_unless($this->stations($request)->contains((int)$data['station_id']),403);DB::transaction(function()use($request,$data){$category=DB::table('expense_categories')->where('station_id',$data['station_id'])->where('name',$data['category'])->first();$categoryId=$category?->id??DB::table('expense_categories')->insertGetId(['station_id'=>$data['station_id'],'name'=>$data['category'],'created_at'=>now(),'updated_at'=>now()]);$id=DB::table('expenses')->insertGetId(['station_id'=>$data['station_id'],'category_id'=>$categoryId,'created_by'=>$request->user()->id,'expense_date'=>$data['expense_date'],'amount'=>$data['amount'],'payment_mode'=>$data['payment_mode'],'remarks'=>$data['remarks']??null,'created_at'=>now(),'updated_at'=>now()]);DB::table('audit_logs')->insert(['user_id'=>$request->user()->id,'station_id'=>$data['station_id'],'action'=>'expense_created','entity_type'=>'expense','entity_id'=>$id,'details'=>json_encode(['amount'=>$data['amount'],'category'=>$data['category']]),'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Expense recorded.');}
    public function destroy(Request $request,int $expense){abort_unless($request->user()->hasPermission('expenses.manage'),403);$row=DB::table('expenses')->where('id',$expense)->whereNull('deleted_at')->first();abort_unless($row && $this->stations($request)->contains($row->station_id),404);DB::transaction(function()use($request,$row){DB::table('expenses')->where('id',$row->id)->update(['deleted_at'=>now(),'updated_at'=>now()]);DB::table('audit_logs')->insert(['user_id'=>$request->user()->id,'station_id'=>$row->station_id,'action'=>'expense_deactivated','entity_type'=>'expense','entity_id'=>$row->id,'details'=>null,'created_at'=>now(),'updated_at'=>now()]);});return back()->with('success','Expense deactivated.');}
}
